import 'dart:async';
import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/gestures.dart';
import 'package:flutter/material.dart';
import 'package:webview_flutter/webview_flutter.dart';

import 'salah_models.dart';

// The owner's schematic 3D scene (docs/salah/salah-3d.md) as an addition to the
// course pictures. assets/salah3d holds the same scene the site runs: its
// salah-scene.js and three.min.js are generated by
// services/web/scripts/salah3d-app-assets.ts. Mirrors services/web/lib/salah-3d.ts.

/// Course `position` → the scene pose that shows it.
const salahSceneByPosition = <String, String>{
  'qiyam': 'qiyam',
  'takbir': 'takbir',
  'ruku': 'ruku',
  'itidal': 'itidal',
  'sujud': 'sujud',
  'jalsa': 'jalsa',
  'tashahhud': 'tashahhud',
  'taslim': 'salam',
};

/// The scene step for each course step, or null where the scene has no such
/// pose (qunut, tawarruk, wudu) or the step has no picture to switch from.
List<String?> salahSceneSteps(List<SalahStep> steps) {
  String? sitting;
  return <String?>[
    for (var index = 0; index < steps.length; index++)
      () {
        final step = steps[index];
        final position = step.position;
        if (position == 'tashahhud' || position == 'tawarruk') {
          sitting = position;
        }
        final scene = salahSceneByPosition[position];
        if (step.media == null || scene == null) return null;
        // The second prostration comes from the sitting between the two.
        if (scene == 'sujud' &&
            index > 0 &&
            steps[index - 1].position == 'jalsa') {
          return 'sujud2';
        }
        // The scene greets from iftirash; after tawarruk its pose is wrong.
        if (scene == 'salam' && sitting == 'tawarruk') return null;
        return scene;
      }(),
  ];
}

const salahSceneSpeeds = <double>[1, .75, .5];

/// The lesson's 3D choice: off until chosen, and while the lesson stays open
/// it follows the steps. Any failure brings the pictures back for the rest of
/// the visit.
class Salah3DController extends ChangeNotifier {
  bool _chosen = false;
  bool _failed = false;
  bool _ready = false;
  bool _playing = true;
  double _speed = 1;
  int _resetCount = 0;
  bool _notice = false;

  bool get chosen => _chosen && !_failed;
  bool get failed => _failed;
  bool get ready => _ready;
  bool get playing => _playing;
  double get speed => _speed;
  int get resetCount => _resetCount;

  /// 3D has just failed: the current step says that the picture stays.
  bool get notice => _notice;

  void choose(bool threeD) {
    if (_failed || _chosen == threeD) return;
    _chosen = threeD;
    _ready = false;
    notifyListeners();
  }

  void markReady() {
    if (_ready || !chosen) return;
    _ready = true;
    notifyListeners();
  }

  void fail() {
    if (_failed) return;
    _failed = true;
    _notice = true;
    _ready = false;
    notifyListeners();
  }

  /// A new step starts loading its own scene and drops the failure note.
  void stepChanged() {
    if (!_ready && !_notice) return;
    _ready = false;
    _notice = false;
    notifyListeners();
  }

  void togglePlaying() {
    _playing = !_playing;
    notifyListeners();
  }

  void cycleSpeed() {
    final next = salahSceneSpeeds.indexOf(_speed) + 1;
    _speed = salahSceneSpeeds[next % salahSceneSpeeds.length];
    notifyListeners();
  }

  void resetView() {
    _resetCount++;
    notifyListeners();
  }
}

/// What the 3D view of one step is asked to show.
@immutable
class Salah3DViewConfig {
  const Salah3DViewConfig({
    required this.step,
    required this.running,
    required this.speed,
    required this.resetCount,
    required this.onReady,
    required this.onError,
  });

  /// A scene step id, for example `ruku`.
  final String step;

  /// Playing, with the app in the foreground and the lesson on screen.
  final bool running;
  final double speed;
  final int resetCount;
  final VoidCallback onReady;
  final ValueChanged<String> onError;
}

typedef Salah3DViewBuilder =
    Widget Function(BuildContext context, Salah3DViewConfig config);

/// The real view: the bundled page in a WebView. Tests replace it.
Widget buildSalah3DWebView(BuildContext context, Salah3DViewConfig config) =>
    Salah3DWebView(config: config);

/// The scene from assets/salah3d in a WebView, offline. Only the bundled page
/// may load; the page talks back through the `SalahBridge` channel.
class Salah3DWebView extends StatefulWidget {
  const Salah3DWebView({required this.config, super.key});

  final Salah3DViewConfig config;

  @override
  State<Salah3DWebView> createState() => _Salah3DWebViewState();
}

class _Salah3DWebViewState extends State<Salah3DWebView> {
  late final WebViewController _web;
  Timer? _timeout;
  var _shown = false;

  // Horizontal drags turn the figure and pinches zoom; vertical drags still
  // scroll the step.
  static final _gestures = <Factory<OneSequenceGestureRecognizer>>{
    Factory<OneSequenceGestureRecognizer>(HorizontalDragGestureRecognizer.new),
    Factory<OneSequenceGestureRecognizer>(ScaleGestureRecognizer.new),
  };

  Salah3DViewConfig get _config => widget.config;

  @override
  void initState() {
    super.initState();
    _web = WebViewController()
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      ..setBackgroundColor(const Color(0xFFF1EDE4))
      ..addJavaScriptChannel('SalahBridge', onMessageReceived: _onMessage)
      ..setNavigationDelegate(
        NavigationDelegate(
          onNavigationRequest: (request) =>
              request.url.startsWith('file:') ||
                  request.url.startsWith('about:')
              ? NavigationDecision.navigate
              : NavigationDecision.prevent,
          onWebResourceError: (error) {
            if (error.isForMainFrame ?? true) _config.onError('LOAD_FAILED');
          },
        ),
      );
    _timeout = Timer(const Duration(seconds: 20), () {
      if (!_shown) _config.onError('TIMEOUT');
    });
    unawaited(
      _web.loadFlutterAsset('assets/salah3d/index.html').catchError((_) {
        _config.onError('LOAD_FAILED');
      }),
    );
  }

  @override
  void didUpdateWidget(Salah3DWebView oldWidget) {
    super.didUpdateWidget(oldWidget);
    final old = oldWidget.config;
    if (old.running != _config.running) {
      _run(_config.running ? 'salah.play()' : 'salah.pause()');
    }
    if (old.speed != _config.speed) _run('salah.setSpeed(${_config.speed})');
    if (old.resetCount != _config.resetCount) _run('salah.resetCamera()');
    if (old.step != _config.step) {
      _run('salah.show(${jsonEncode(_config.step)})');
    }
  }

  @override
  void dispose() {
    _timeout?.cancel();
    _run('salah.dispose()');
    super.dispose();
  }

  void _run(String command) {
    unawaited(
      _web.runJavaScript('window.salah && $command').catchError((Object _) {}),
    );
  }

  void _onMessage(JavaScriptMessage message) {
    Object? decoded;
    try {
      decoded = jsonDecode(message.message);
    } on FormatException {
      return;
    }
    if (!mounted || decoded is! Map<String, Object?>) return;
    switch (decoded['type']) {
      case 'LOADED':
        _run('salah.show(${jsonEncode(_config.step)}, ${_config.speed})');
      case 'READY':
        _timeout?.cancel();
        if (!_config.running) _run('salah.pause()');
        setState(() => _shown = true);
        _config.onReady();
      case 'ERROR':
        _timeout?.cancel();
        _config.onError('${decoded['code']}');
    }
  }

  @override
  Widget build(BuildContext context) {
    // Hidden until the first frame is drawn: the picture underneath shows.
    return ExcludeSemantics(
      child: AnimatedOpacity(
        opacity: _shown ? 1 : 0,
        duration: const Duration(milliseconds: 200),
        child: WebViewWidget(controller: _web, gestureRecognizers: _gestures),
      ),
    );
  }
}
